            else:
                # R21: bump ignored; R24: dig ignored
                ns = FALL_RIGHT
                nfc = fall_count + 1
        elif state == DIG_LEFT:
            if ground == 0:
                # R18: dig reaches other side -> fall
                ns = FALL_LEFT
                nfc = 1
            else:
                # R19, R24: keep digging, bumps ignored
                ns = DIG_LEFT
                nfc = 0
        elif state == DIG_RIGHT:
            if ground == 0:
                # R18: fall
                ns = FALL_RIGHT
                nfc = 1
            else:
                # R19, R24: keep digging
                ns = DIG_RIGHT
                nfc = 0

        state = ns
        fall_count = nfc

    return result
